---InitSuitInfoList
---@param suitInfo table<number, number> 套装信息
---@return table suitInfoList 套装信息列表
function UICultivateEquipDiySuitDialog:InitSuitInfoList(suitInfo)
    local suitInfoList = {}
    for suitId, partCount in pairs(suitInfo) do
        table.insert(suitInfoList, {suitId = suitId, partCount = partCount})
    end
    table.sort(suitInfoList, function(a, b)
        return a.partCount > b.partCount
    end)
    return suitInfoList

end

---InitDiySuits
---初始化自定义套装
function UICultivateEquipDiySuitDialog:InitDiySuits()
    ---------------------------
    --- 初始化当前卡牌套装数据
    --local cardDojo    = self:GetCardDojo()
    local equipIdList = self:GetEquipIdList()
    local suits       = {
        {
            suitId = EmptyDiySuitFlag,
        },
        {
            suitId = CurrentDiySuitFlag,
            equipIdList = equipIdList,
            playerEquipmentCoreId = self.playerEquipmentCoreId
        }
    }

    ---------------------------
    --- 初始化自定义套装数据
    local diySuits = equipComp:GetDiySuits()

    local split = string.split
    ---@param v table {suitId, name, playerEquipmentCoreId, equipments}
    for i, v in ipairs(diySuits) do
        local suitId = checkNumber(v.suitId)
        if suitId > 0 then
            local playerEquipmentCoreId = checkNumber(v.playerEquipmentCoreId)
            local suitIsCurEquip = playerEquipmentCoreId == self.playerEquipmentCoreId
            local idList = {0, 0, 0, 0}
            local suitEquipIdList = split(v.equipments, ',')
            for key, equipId in pairs(suitEquipIdList) do
                idList[key] = checkInt(equipId)
                suitIsCurEquip = suitIsCurEquip and (idList[key] == equipIdList[key])
            end
            table.insert(suits, {
                name                  = v.name,
                suitId                = suitId,
                equipIdList           = idList,
                suitIsCurEquip        = suitIsCurEquip,
                playerEquipmentCoreId = playerEquipmentCoreId
            })
        end
    end
    table.sort(suits,function(a, b)
        return a.suitId < b.suitId
    end)

    self.diySuits = suits
end


