    local tempIndex
    if not isEdit then
        local suitData   = {name = text, suitId = suitId, equipIdList = equipIdList, playerEquipmentCoreId = playerEquipmentCoreId, suitIsCurEquip = true}
        --if count >= MaxDiySuitCount + 2 then
        --    table.remove(self.diySuits)
        --    count = count - 1
        --end
        tempIndex = suitId + 2

        table.insert(self.diySuits, tempIndex, suitData)
    else
        local data = self.diySuits[self.selectDiySuitIndex]
        data.name = text
        data.suitId = suitId
        data.equipIdList = equipIdList
        data.playerEquipmentCoreId = playerEquipmentCoreId
        data.suitIsCurEquip = true
    end

    return tempIndex
end

