---OnGetFollowerListItemByIndex 随从列表刷新回调
---@param listView SuperScrollView.LoopListView2 列表对象
---@param index number c#中的index
---@return  SuperScrollView.LoopGridViewItem
function UICultivateEquipDiySuitDialog:OnGetItemByIndex(listView, index)
    local position = index + 1
    if position < 1 then
        return nil
    end

    --- 创建cell
    local cell = listView:NewListViewItem(PrefabName)
    if not KTool.IsNull(cell) then
        --- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabMBPath)
        if not KTool.IsNull(cellViewMB) then
            --local Background = cell.transform:Find("Background")
            ---@type UICultivateEquipDiySuitSuitNodeMB
            local cellEnv = cellViewMB.Env
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                cellEnv = cellViewMB.Env
                cellEnv:SetCallback(Bind(self, self.OnClickCellActon))
            end

            if cellEnv then
                local suitData = self.diySuits[position] or {}
                cellEnv:RefreshUI(suitData, position)
                cellEnv:RefreshSelectState(self.selectDiySuitIndex == position)
            end

        end
    end

    return cell
end

