---RefreshDiySuitScrollView
---刷新组合列表
function UICultivateEquipDiySuitDialog:RefreshDiySuitScrollView(index)
    local SuitScrollView = self.SuitScrollView
    local diySuitCount   = #self.diySuits
    if not SuitScrollView.IsListViewInit then
        SuitScrollView:InitGridView(diySuitCount, Bind(self, self.OnGetItemByIndex))
