function UICultivateEquipDiySuitDialog:OnSaveDiySuitListener(suitId, text, equipments, equipIdList, playerEquipmentCoreId, isEdit)
    local tempIndex = self:AddDiySuitData(suitId, text, equipIdList, playerEquipmentCoreId, isEdit)
    if isEdit then
        equipComp:UpdateDiySuitBySuitId(suitId, text, equipments, playerEquipmentCoreId)
    else
        equipComp:AddDiySuitBySuitId(suitId, text, equipments, playerEquipmentCoreId)
    end

    if tempIndex then
        self.selectDiySuitIndex = tempIndex
    end

    self:RefreshDiySuitScrollView(tempIndex)

    self:RefreshEquipNodeGroup()

    self:RefreshDiySuitCountText()

    self:RefreshBottomNode()
end

