---GetSuitId
---@param suitId number 套装Id
---@return number suitId 套装Id
function UICultivateEquipDiySuitDialog:GetSuitId(suitId)
    if suitId and suitId > 0  then return suitId end

    local suits = self.diySuits
    local len = #suits
    --- 长度为1 那么就只有 当前套装
    if len == 2 then return 1 end

    if len == MaxDiySuitCount + 2 then return -1 end

    suits = clone(suits)
    table.sort(suits, function(a, b)
        return a.suitId < b.suitId
    end)

    local newSuitId = 1
    for i = 1, MaxDiySuitCount do
        local suitData = suits[i + 2]

        if suitData == nil then
            newSuitId = i
            break
        end

        local suitDataId = checkNumber(suitData.suitId)
        if suitDataId > 0 then
            if suitDataId ~= i then
                newSuitId = i
                break
            end
        end
    end

    return newSuitId
end

