---CheckEquipIdListIsEffective
---检查装备id列表是否有效
---@param equipIdList table
---@return table UsedCardIdList 被使用的卡牌id列表
function UICultivateEquipDiySuitDialog:GetUsedCardIdListByEquipIdList(equipIdList, usedCardIdList)
    local playerEquipId
    local playerCardId = checkNumber(self:GetPlayerCardId())
    for i, equipId in ipairs(equipIdList) do
        if checkNumber(equipId) > 0 then
            playerEquipId = checkNumber(equipId)
            local equipDojo = equipComp:GetEquipById(playerEquipId)
            local oldPlayerCardId = checkNumber(equipDojo.playerCardId)
            if playerCardId > 0 and oldPlayerCardId > 0 and playerCardId ~= oldPlayerCardId then
                table.insert(usedCardIdList, {playerCardId = oldPlayerCardId, id = playerEquipId})
            end
        end
    end
    return usedCardIdList
end

