function UICultivateEquipDiySuitDialog:OnClickCurrentSuitAction()
    if self.selectDiySuitIndex == CurrentDiySuitFlag then
        return
    end
    if self.selectDiySuitIndex > 0 then
        local cell = self.SuitScrollView:GetShownItemByItemIndex(self.selectDiySuitIndex - 1)
        if cell then
            local oldMB = KTool.GetComponent(cell.gameObject, typeof(LuaBehaviour))
            oldMB.Env:RefreshSelectState(false)
        end
    end
    self.selectDiySuitIndex = 0
    self:RefreshRightUIShowState()
end

function UICultivateEquipDiySuitDialog:OnClickCellActon(index)
    if index == self.selectDiySuitIndex then
        return
    end

    local suitData = self.diySuits[index]
    local suitId = suitData.suitId
    local isNew = suitId == EmptyDiySuitFlag
    if isNew then
        if #self.diySuits == MaxDiySuitCount + 2 then
            GameUtils.Toast(localize('自定义套装已满'))
            return
        end
        self.isNew = isNew
        self:OnClickEditButtonAction()
        return
    end

    local cell = self.SuitScrollView:GetShownItemByItemIndex(self.selectDiySuitIndex - 1)
    if cell then
        local oldMB = KTool.GetComponent(cell.gameObject, typeof(LuaBehaviour))
        oldMB.Env:RefreshSelectState(false)
    end

    cell = self.SuitScrollView:GetShownItemByItemIndex(index - 1)
    if cell then
        local newMB = KTool.GetComponent(cell.gameObject, typeof(LuaBehaviour))
        newMB.Env:RefreshSelectState(true)
    end

    self.selectDiySuitIndex = index
    self:RefreshRightUIShowState()

end

function UICultivateEquipDiySuitDialog:OnClickDeleteButtonAction()
    GameUtils.SecondConfirm(localize("确定删除？"), function()
        local suitData = self.diySuits[self.selectDiySuitIndex]
        GameUtils.Request(Interfaces.EquipmentDeleteDiySuit, { suitId = suitData.suitId }, function(request, response)
            if checkInt(response.errCode) == 0 then
                local suitId = checkNumber(suitData.suitId)
                equipComp:RemoveDiySuitBySuitId(suitId)
                self:RemoveDiySuitData()

                self:RefreshUI()
            end
        end)
    end)
end

function UICultivateEquipDiySuitDialog:OnClickEditButtonAction()
    local newSuitId, suitData, isEdit, selectIndex
    if self.isNew then
        suitData = {}
        newSuitId = self:GetSuitId()
    else
        suitData = self.diySuits[self.selectDiySuitIndex]
        local suitId = checkNumber(suitData.suitId)
        newSuitId = self:GetSuitId(suitId)
        isEdit = true
        selectIndex = self.selectDiySuitIndex
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateEquipDiySuitEditDialog,
                          parameters = {
                               suitData = suitData,
                               playerCardId = self:GetPlayerCardId(),
                               part = self.part,
                               newSuitId = newSuitId,
                               isEdit = isEdit,
                               selectIndex = selectIndex
                          }
    }, {{id = Constants.UITypeIds.UICultivateEquipDiySuitDialog}})

end

function UICultivateEquipDiySuitDialog:OnClickReplaceButtonAction()

    local suitData = self.diySuits[self.selectDiySuitIndex]
    local suitId   = suitData.suitId
    if suitId == CurrentDiySuitFlag or suitId == EmptyDiySuitFlag then
        return
    end

    local equipIdList = suitData.equipIdList or {}
    local playerEquipmentCoreId = checkNumber(suitData.playerEquipmentCoreId)
    local firstPlayerEquipId = EquipUtils.GetFirstEquipId(equipIdList)
    if firstPlayerEquipId <= 0 and playerEquipmentCoreId <= 0 then
        GameUtils.Toast(localize("至少装备一个装备"))
        return
    end

    ---检查职业限制
    local career   = self.career
    local equipmentCoreDojo
    if playerEquipmentCoreId > 0 then
        equipmentCoreDojo = equipComp:GetEquipCoreById(playerEquipmentCoreId)
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreDojo.equipmentCoreId)
        local occupationId = equipCoreVo.occupationId
        if career > 0 and occupationId > 0 and career ~= occupationId then
            GameUtils.Toast(localize("核心职业不符, 无法使用该套装"))
            return
        end
    end

    local playerCardId = checkNumber(self:GetPlayerCardId())
    local usedCardIdList = {}
    if equipmentCoreDojo and checkNumber(equipmentCoreDojo.playerCardId) > 0 and playerCardId ~= checkNumber(equipmentCoreDojo.playerCardId) then
        table.insert(usedCardIdList, {playerCardId = checkNumber(equipmentCoreDojo.playerCardId), id = playerEquipmentCoreId, part = -1})
    end
    self:GetUsedCardIdListByEquipIdList(equipIdList, usedCardIdList)
    if next(usedCardIdList) == nil then
        self:UpdateCacheData(equipIdList, playerEquipmentCoreId)
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateEquipReplaceTipDialog,
          parameters = {
              usedCardIdList = usedCardIdList,
              titleName = localize("当前组合中有被其他武装装备的涂鸦，是否替换"),
              cb = function()
                  self:UpdateCacheData(equipIdList, playerEquipmentCoreId)
                  --self:ExecuteEquipmentEquipRequest()
                  --UIModule.BackDialog()
              end
          }
    })

end

function UICultivateEquipDiySuitDialog:UpdateCacheData(equipIdList, playerEquipmentCoreId)
    GameUtils.Toast(localize("套装替换成功"))
    self:SetEquipIdList(equipIdList)
    self.playerEquipmentCoreId = playerEquipmentCoreId

    local curCardSuitData = self.diySuits[CurrentEquipIndex]
    curCardSuitData.equipIdList = clone(equipIdList)
    curCardSuitData.playerEquipmentCoreId = playerEquipmentCoreId

    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    cardComp:AddEquipData(self:GetPlayerCardId(), equipIdList, playerEquipmentCoreId)

    self.selectDiySuitIndex  = CurrentEquipIndex


    for i, v in ipairs(self.diySuits) do
        local suitCoreId      = v.playerEquipmentCoreId
        local suitEquipIdList = v.equipIdList
        local suitIsCurEquip  = suitCoreId == playerEquipmentCoreId
        if suitIsCurEquip then
            for part, id in ipairs(suitEquipIdList) do
                suitIsCurEquip = suitIsCurEquip and id == equipIdList[part]
            end
        end
        v.suitIsCurEquip = suitIsCurEquip
    end

    self:RefreshUI()
end

function UICultivateEquipDiySuitDialog:OnClickDetermineButtonAction()
    local text = self.InputField.text
    if not Constants.MODULE_SWITCH.Is_Read_Only then
        if string.isEmpty(text) then
            GameUtils.Toast(localize('自定义套装名称不能为空'))
            return
        end
    end

    local suitData = self.diySuits[CurrentEquipIndex]
    local equipIdList = suitData.equipIdList
    local playerEquipmentCoreId = self.playerEquipmentCoreId
    if not EquipUtils.CheckIsInstallEquip(equipIdList) and playerEquipmentCoreId <= 0 then
        GameUtils.Toast(localize('自定义套装装备不能为空'))
        return
    end

    local count = #self.diySuits
    if count == MaxDiySuitCount + 2 then
        GameUtils.Toast(localize('自定义套装已满'))
        return
    end

    local suitId      = self:GetSuitId()
    local equipments  = table.concat(equipIdList, ',')
    local name = Constants.MODULE_SWITCH.Is_Read_Only and suitId or text
    GameUtils.Request(Interfaces.EquipmentSaveDiySuit, {
        suitId = suitId,
        name = name,
        isNew = 1,
        playerEquipmentCoreId = playerEquipmentCoreId,
        equipments = equipments},
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    self.InputField.text = ""
                    GameUtils.Toast(localize("套装保存成功"))
                    self:OnSaveDiySuitListener(suitId, name, equipments, equipIdList, playerEquipmentCoreId)
                end
            end)
end

---------------------------------------------------
--- click handler end --
---------------------------------------------------

function UICultivateEquipDiySuitDialog:OnDiySuitEditQuitListener(selectIndex, newSuitId)
    if selectIndex then
        self:OnClickCellActon(selectIndex)
        return
    end
    for i, suitData in ipairs(self.diySuits) do
        if suitData.suitId == newSuitId then
            self:OnClickCellActon(i)
            break
        end
    end
end

function UICultivateEquipDiySuitDialog:ExecuteEquipmentEquipRequest()
    local equipIdList     = self:GetEquipIdList()
    local isChange        = false
    local equipmentIdList = {}
    local originalEquipIdList = self.originalEquipIdList
    for i = 1, Constants.CardEquipmentNo do
        local originalEquipId = checkNumber(originalEquipIdList[i])
        local equipId = checkNumber(equipIdList[i])
        if originalEquipId ~= equipId then
            isChange = true
        end
        equipmentIdList[tostring(i)] = equipId
    end

    local equipmentCore = self.playerEquipmentCoreId
    if not isChange then
        isChange = self.originalEquipmentCoreId ~= equipmentCore
    end

    if isChange then
        GameUtils.Request(Interfaces.EquipmentEquip, {playerEquipmentCoreId = equipmentCore, playerCardId = self:GetPlayerCardId(), equipment = table.serialize(equipmentIdList) }, function(request, response)
            if checkInt(response.errCode) ~= 0 then return end
            UIModule.BackDialog()
        end)
    else
        UIModule.BackDialog()
    end
end
return UICultivateEquipDiySuitDialog